    "2cabeb8a": {"text":"ein königliches oder regierendes Haus","hash":"h1-fef51cd5"},
    "2cb1fb99": {"text":"Samarkand","hash":"h1-59500da5"},
    "2cb2b02b": {"text":"Bremen","hash":"h1-ead0b748"},
    "2cb3b220": {"text":"wechselt zwischen den Schaltflächen.","hash":"h1-2e81cd3a"},
