    "39e89c0e": {"forms":{"select":"value","param":"case","cases":{"player_self":"🎓 Sie übernehmen die Leitung des Unterrichts von {name}.","named_self":"🎓 {tutor} übernimmt Ihren Unterricht.","named_other":"🎓 {tutor} übernimmt den Unterricht von {name}.","other":"🎓 Ein Tutor übernimmt die Leitung des {name}-Unterrichts."}},"hash":"h1-8cd0b3d0"},
    "39ecdbcd": {"text":"{name} verwerfen","hash":"h1-fa20d3b5"},
    "39eeb233": {"text":"Eine Ehrensache","hash":"h1-7e061c80"},
    "39f54b85": {"text":"Will mehr. Immer mehr.","hash":"h1-960f7c3b"},
