    "50201f0f": {"text":"– Fällt bei Nichtlandung auf den nackten Rang zurück */ FB.styledTitle = function (state) { return FB.renderTitleSnapshot(FB.titleSnapshot(state)); }; FB.titleSnapshot = function (state) { const p = state.player; const me = state.chars[p.charId]; const rank = rankTitleRecord(state, me.religion, me.sex, p.tier); let group = FB.faithGroup(me.religion, state) || 'Christian'; if (me.sex === 'f' && FBDATA.titles[group + '_f']) group += '_f'; const snap = { group:group, religion:me.religion, titleReligion:rank.sourceId || null, titleSex:rank.sex || me.sex, tier:rank.tier, word:rank.word }; if (FB.playerPope && FB.playerPope(state)) { snap.headReligion = me.religion; const head = FB.faithValue(state, me.religion, 'head.title'); snap.headTitleReligion = head.sourceId || me.religion; snap.headTitle = head.value || 'Papst'; Rückholknopf; } if (FB.playerCardinal && FB.playerCardinal(state)) { snap.special = 'cardinal'; snapshotFaithRole(snap, state, me.religion, 'cardinal'); Rückholknopf; } const headed = FB.religionsHeadedBy(state, 'player'); if (headed.length) { const headReligion = headed[0]; snap.headReligion = headReligion; const head = FB.faithValue(state, headReligion, 'head.title'); snap.headTitleReligion = head.sourceId || headReligion; snap.headTitle = head.value; Rückholknopf; } const castellany = FB.castellanyOf && FB.castellanyOf(state); if (castellany) { snap.special = 'castellan'; const castleCounty = FB.world && FB.world.byId[castellany.provinceId]; snap.place = castleCounty ? castleCounty.name : castellany.provinceId; Rückholknopf; } if (p.tier","hash":"h1-b9ec6e3d"},
