    "b8cccc37": {"text":"Lass sie davon müde werden.","hash":"h1-f4b67e1a"},
    "b8d3f205": {"text":"Litauer","hash":"h1-914bb12b"},
    "b8d76acb": {"text":"Ordnung ernährt mehr Reisende als gute Absichten allein.","hash":"h1-41300ac3"},
    "b8dab425": {"text":"Reservieren","hash":"h1-ecf420fb"},
    "b8eaab98": {"text":"Tallage ohne Maß","hash":"h1-5dd39e61"},
