    "cef8a1ee": {"text":"20) return { ok:false, reason:'long' }; if (!houseNameCharsOk(nm)) return { ok:false, reason:'chars' }; return { ok:true, name:nm }; }; /* Ein Haus ist nur die c.dyn-Zeichenfolge, die seine Mitglieder gemeinsam haben, daher wird bei einer Umbenennung jedes Zeichen neu geschrieben, das die alte Zeichenfolge trägt – dieselbe Mitgliedschaftsregel, die FB.dynastyNameSet verwendet – sowie die Player-Realm-Identität, als sie vom Haus abgeleitet wurde. Persönliche Namen und Beinamen bleiben unberührt, und bereits geschriebene Chronik- oder Legendentexte behalten den alten Namen. Die Heraldik wird aus der Dyn-Schnur gesät, daher wird das Wappen neu gezeichnet. */ FB.renameHouse = function (state, newName) { const me = state && state.player && state.chars && state.chars[state.player.charId]; if (!me || !me.dyn) return { ok:false, reason:'nohouse' }; const oldDyn = me.dyn; const check = FB.validateHouseName(newName, oldDyn); if (!check.ok) return check; const nm = check.name; for (const id in state.chars) { const c = state.chars[id]; if (c && c.dyn === oldDyn) c.dyn = nm; } const realm = state.realms && state.realms.player; if (realm) { if (realm.name === 'Realm of ' + oldDyn) realm.name = 'Realm of ' + nm; if (realm.dynasty === oldDyn) realm.dynasty = nm; } FB.touchFamily(); FB.news(state, FB.msg('news.house.renamed', '👑 Das Haus von {old} ist fortan als {dynasty} bekannt.', { old:oldDyn, dynasty:nm })); return { ok:true, name:nm, old:oldDyn }; }; /* ---------- Zeichenfabrik ---------- opts: {Geschlecht, Kultur, Religion, geboren, Dyn, Rolle, Qualität (Fähigkeitsbonus), MerkmaleN} opts.id installiert eine vom Anrufer abgeleitete Identität, anstatt die nächste sequentielle UID zu zeichnen. Gerichtsakten verwenden es, damit dasselbe Nachfolgemitglied immer dieselbe Charakter-ID erhält, unabhängig davon, ob diese bei der Welterstellung erstellt wurde oder in dem Moment, als ein Spieler das Reich zum ersten Mal öffnete. */ FB.makeCharacter = function (state, opts) { const sex = opts.sex || (FB.chance(0.5) ? 'm' : 'f'); const c = { id: opts.id || FB.uid(), Name: opts.name || FB.randomName(opts.culture, sex, opts.dyn ? FB.dynastyNameSet(state, opts.dyn) : null), Geschlecht: Sex, Kultur: opts.culture, Religion: opts.religion, geboren: opts.born, tot: false, dyn: opts.dyn || null, Rolle: opts.role || null, Merkmale: opts.traits || [], Fähigkeiten: {}, Meinung: opts.opinion !== undefiniert ? opts.opinion: 0, Fruchtbarkeit: FB.rf(0.7, 1.3), Station: opts.station !== undefiniert? opts.station: null, Ehepartner-ID: null, Vater-ID: opts.fatherId || null, motherId: opts.motherId || null, childIds: [] }; /* Die explizite Meinung bleibt eine exakt verfasste Gesamtsumme. Ein neu angetroffener neutraler Charakter beginnt stattdessen an der aktuellen Basislinie des Richtungsglaubens, und die Markierung lässt zu, dass spätere Schismen nur diese Komponente umbasieren. */ const playerCharacter = state && state.player && state.chars && state.chars[state.player.charId]; if (playerCharacter && playerCharacter.id !== c.id && FB.faithRelationBaseline) { const believeBase = FB.faithRelationBaseline( state, c.religion, playerCharacter.religion); c.faithStandingBase = believeBase; if (opts.opinion === undefiniert) c.opinion = believeBase; } if (Object.prototype.hasOwnProperty.call(opts, 'byname')) { c.byname = opts.byname; } else if (state && FB.cultureOf(c.culture).dyn === 'patronym' && c.fatherId && state.chars[c.fatherId]) { c.byname = FB.patronym(state.chars[c.fatherId].name, c.sex); } const q = opts.quality || 0; for (const s of SKILLS) c.skills[s] = Math.max(0, FB.ri(0, 6) + q); if (!opts.traits) { const pool = Object.keys(FBDATA.traits).filter(function (t) { return !FBDATA.traits[t].noRandom; }); const n = opts.traitsN !== undefiniert ? opts.traitsN : FB.ri(1, 3); für (sei i = 0; i","hash":"h1-d15f60e3"},
